CREATE OR REPLACE EDITIONABLE PROCEDURE "%USER_NAME%"."COPY_TYPE_GROUP" (p_drop_down_type_id in number, p_type_name in varchar2)
as
    l_drop_down_type_id number;
begin
    insert into drop_down_type(type_name)
    values (p_type_name)
    returning drop_down_type_id
    into l_drop_down_type_id;

    insert into drop_down_type_entry(drop_down_type_id, entry, value, extra)
    select l_drop_down_type_id, entry, value, extra
    from drop_down_type_entry
    where drop_down_type_id = p_drop_down_type_id;

    commit;
end copy_type_group;
/
